<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; class EmailCampaign extends Model {protected $fillable=['name','subject','html_body','audience','status','total_count','sent_count','failed_count','started_at','completed_at','cancelled_at']; protected $casts=['started_at'=>'datetime','completed_at'=>'datetime','cancelled_at'=>'datetime']; public function recipients():HasMany{return $this->hasMany(EmailCampaignRecipient::class);}}
